import { test, expect } from '@playwright/test';

test.describe('Form Autocomplete Attributes', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form'); // Replace with the actual URL of the form
  });

  test('should have autocomplete attribute set for username field', async ({ page }) => {
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toHaveAttribute('autocomplete', 'username');
  });

  test('should have autocomplete attribute set for email field', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    await expect(emailInput).toHaveAttribute('autocomplete', 'email');
  });
});
